    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    walls = [r for r, row in enumerate(out) if 8 in row]
    if not walls:
        return out
    holes = {r: [c for c, v in enumerate(out[r]) if v == 0] for r in walls}
    # Keep marker locations; the seed is the blue cell in the top region.
    seed = next((c for row in out for c, v in enumerate(row) if v == 2), w // 2)

    # Connect the seed to the first barrier's openings.
    first = walls[0]
    if first > 0 and holes[first]:
        lo, hi = min([seed] + holes[first]), max([seed] + holes[first])
        for c in range(lo, hi + 1):
            if out[first - 1][c] == 0:
                out[first - 1][c] = 2

    # Paint connections between consecutive horizontal barriers. Vertical
    # stems from the upper openings join a horizontal segment just above the
    # next barrier; the horizontal span reaches every opening of both walls.
    for upper, lower in zip(walls, walls[1:]):
        upper_holes, lower_holes = holes[upper], holes[lower]
        rows_between = list(range(upper + 1, lower))
        if not rows_between:
            continue
        if upper_holes and lower_holes:
            lo = min(upper_holes + lower_holes)
            hi = max(upper_holes + lower_holes)
            for r in rows_between[:-1]:
                for c in upper_holes:
                    if out[r][c] == 0:
                        out[r][c] = 2
            r = rows_between[-1]
            for c in range(lo, hi + 1):
                if out[r][c] == 0:
                    out[r][c] = 2

    # Continue downward from each opening in the final barrier.
    for r in range(walls[-1] + 1, h):
        for c in holes[walls[-1]]:
            if out[r][c] == 0:
                out[r][c] = 2

    # Color all barrier openings in the traced path.
    for r in walls:
        for c in holes[r]:
            out[r][c] = 2
    return out


