 "content": "from collections import deque


def transform(grid):
    """Trace and split a beam as it follows gaps through straight 8-walls."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    q = deque()
    seen = set()

    # The marker is placed at an edge; start pointing inward from that edge.
    start = next(((r, c) for r, row in enumerate(grid)
                  for c, value in enumerate(row) if value == 2), None)
    if start is None:
        return out
    r, c = start
    if r == 0:
        direction = (1, 0)
    elif r == h - 1:
        direction = (-1, 0)
    elif c == 0:
        direction = (0, 1)
    elif c == w - 1:
        direction = (0, -1)
    else:
        # Fallback for a marker away from the border: aim toward the nearest edge.
        distances = [(r, (-1, 0)), (h - 1 - r, (1, 0)),
                     (c, (0, -1)), (w - 1 - c, (0, 1))]
        direction = min(distances, key=lambda item: item[0])[1]
    q.append((r, c, direction[0], direction[1]))

    def paint(rr, cc):
        if grid[rr][cc] != 8:
            out[rr][cc] = 2

    while q:
        r, c, dr, dc = q.popleft()
        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            continue
        if grid[nr][nc] != 8:
            paint(nr, nc)
            q.append((nr, nc, dr, dc))
            continue

        # The beam has hit a wall. It branches in both directions along the
        # adjacent open row/column until it reaches a gap in the wall or edge.
        for sr, sc in ((-dc, dr), (dc, -dr)):
            rr, cc = r, c
            while True:
                rr += sr
                cc += sc
                if not (0 <= rr < h and 0 <= cc < w):
                    break
                if grid[rr][cc] == 8:
                    break
                paint(rr, cc)
                # Check the corresponding cell through the wall. If it is a
                # gap, the ray turns back into its original direction there.
                wr, wc = rr + dr, cc + dc
                if not (0 <= wr < h and 0 <= wc < w):
                    break
                if grid[wr][wc] != 8:
                    paint(wr, wc)
