    walls = [r for r, row in enumerate(grid) if 8 in row]
    if not walls:
        return out
    gaps = {r: [c for c, value in enumerate(grid[r]) if value == 0] for r in walls}
    marker = next(((r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2), (0, w // 2))

    # Approach the first opening from the marker.
    first = walls[0]
    if first > 0 and gaps[first]:
        lo, hi = min([marker[1]] + gaps[first]), max([marker[1]] + gaps[first])
        for c in range(lo, hi + 1):
            if out[first - 1][c] == 0:
                out[first - 1][c] = 2

    # Between walls, openings continue vertically. The row immediately
    # above the next wall joins the open routes across the span of both sets
    # of openings. A single opening in the lower wall fans across that row.
    for upper, lower in zip(walls, walls[1:]):
        for r in range(upper + 1, lower - 1):
            for c in gaps[upper]:
                if out[r][c] == 0:
                    out[r][c] = 2
        r = lower - 1
        all_gaps = gaps[upper] + gaps[lower]
        if all_gaps:
            if len(gaps[lower]) == 1:
                span = range(w)
            else:
