            for c in span:
                if out[r][c] == 0:
                    out[r][c] = 2

    # The final openings continue as vertical lines to the bottom edge.
    for r in walls:
        for c in gaps[r]:
            out[r][c] = 2
    last = walls[-1]
    for r in range(last + 1, h):
        for c in gaps[last]:
            if out[r][c] == 0:
                out[r][c] = 2
    return out


