 "content": "from collections import deque


def transform(grid):
    """Trace the beam inward; at a wall, spread along it to reachable gaps."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    start = next(((r, c) for r, row in enumerate(grid)
                  for c, value in enumerate(row) if value == 2), None)
    if start is None:
        return out

    r, c = start
    if r == 0:
        dr, dc = 1, 0
    elif r == h - 1:
        dr, dc = -1, 0
    elif c == 0:
        dr, dc = 0, 1
    elif c == w - 1:
        dr, dc = 0, -1
    else:
        # Marker is not on the edge: aim toward the nearest border.
        choices = [(r, (-1, 0)), (h - 1 - r, (1, 0)),
                   (c, (0, -1)), (w - 1 - c, (0, 1))]
        _, (dr, dc) = min(choices, key=lambda item: item[0])

    pending = deque([(r, c, dr, dc)])
    seen = set()
    while pending:
        r, c, dr, dc = pending.popleft()
        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            continue

        if grid[nr][nc] != 8:
            out[nr][nc] = 2
            pending.append((nr, nc, dr, dc))
            continue

        # The forward cell is blocked. Follow the adjacent corridor parallel
        # to the wall in each direction; each branch exits through its first
        # opening in the wall, or ends at the grid edge/an obstacle.
        for pr, pc in ((-dc, dr), (dc, -dr)):
            rr, cc = r, c
            while True:
                rr += pr
                cc += pc
                if not (0 <= rr < h and 0 <= cc < w):
                    break
                if grid[rr][cc] == 8:
                    break
                out[rr][cc] = 2
                wr, wc = rr + dr, cc + dc
                if not (0 <= wr < h and 0 <= wc < w):
                    break
                if grid[wr][wc] != 8:
                    out[wr][wc] = 2
                    pending.append((wr, wc, dr, dc))
                    break

    return out


if __name__ == '__main__':
    pass

  ",
